class Solution { public: int countPalindromicSubsequences(string s){int n=s.size();const long long mod=1000000007;vector<vector<long long>> dp(n,vector<long long>(n));for(int i=n-1;i>=0;--i){dp[i][i]=1;for(int j=i+1;j<n;++j){if(s[i]!=s[j])dp[i][j]=dp[i+1][j]+dp[i][j-1]-dp[i+1][j-1];else{int low=i+1,high=j-1;while(low<=high&&s[low]!=s[i])++low;while(low<=high&&s[high]!=s[i])--high;long long inner=dp[i+1][j-1];if(low>high)dp[i][j]=2*inner+2;else if(low==high)dp[i][j]=2*inner+1;else dp[i][j]=2*inner-dp[low+1][high-1];}dp[i][j]=(dp[i][j]%mod+mod)%mod;}}return dp[0][n-1];} };
